import React from 'react';
import {
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';

const CommunicationChannelReport = ({ data }) => {
  // Группируем данные по каналу
  const channelMap = data.reduce((acc, row) => {
    const channel = row.channel || "unknown";
    if (!acc[channel]) {
      acc[channel] = { campaigns: 0, recipients: 0, responded: 0, purchases: 0 };
    }
    acc[channel].campaigns += 1;
    acc[channel].recipients += row["Получателей"];
    acc[channel].responded += row["Среагировавших"];
    acc[channel].purchases += row["Чеков"];
    return acc;
  }, {});

  const channels = Object.keys(channelMap);

  return (
    <Box mb={4}>
      <Typography variant="h6" align="center" gutterBottom>
        Отчёт по каналам коммуникации
      </Typography>
      <TableContainer component={Paper} sx={{ boxShadow: 3, borderRadius: 2 }}>
        <Table size="small">
          <TableHead sx={{ backgroundColor: 'primary.main' }}>
            <TableRow>
              <TableCell sx={{ color: 'white' }}>Канал</TableCell>
              <TableCell align="right" sx={{ color: 'white' }}>Кампаний</TableCell>
              <TableCell align="right" sx={{ color: 'white' }}>Получателей</TableCell>
              <TableCell align="right" sx={{ color: 'white' }}>Реагировавших</TableCell>
              <TableCell align="right" sx={{ color: 'white' }}>Чеков</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {channels.map((channel, idx) => (
              <TableRow key={idx} sx={{ '&:nth-of-type(odd)': { backgroundColor: 'action.hover' } }}>
                <TableCell>{channel}</TableCell>
                <TableCell align="right">{channelMap[channel].campaigns}</TableCell>
                <TableCell align="right">{channelMap[channel].recipients}</TableCell>
                <TableCell align="right">{channelMap[channel].responded}</TableCell>
                <TableCell align="right">{channelMap[channel].purchases}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default CommunicationChannelReport;